  "stages.kind.topaz": { en: "After Topaz", ja: "Topaz後" },
  "stages.kind.final": { en: "Final image", ja: "完成画像" },
  "conditions.open": { en: "Check image conditions", ja: "条件をチェック" },
  "series.open": { en: "Check series consistency", ja: "シリーズの一貫性を確認" },
  "series.title": { en: "Series consistency", ja: "シリーズ画像の一貫性" },
  "series.help": { en: "Compare visible hair, clothing and other features with a reference image. Hidden or ambiguous details remain unknown. This does not identify people or guarantee the same character.", ja: "基準画像と比べて、髪や服などの見た目が揃っているか確認します。見えない部分や曖昧な部分は「不明」です。同一人物の特定や、同じキャラクターであることの保証はしません。" },
  "series.selection": { en: "{count} images selected. Select 2–24 images in the library using Ctrl/Shift; one will be the reference.", ja: "{count}枚選択中。ライブラリでCtrl／Shiftを使って2～24枚を選び、そのうち一枚を基準にします。" },
  "series.reference": { en: "Reference image", ja: "基準画像" },
  "series.candidate": { en: "Image to compare", ja: "比較する画像" },
  "series.criteria": { en: "Aspects to compare — one per line", ja: "比べる項目（一行に一つ）" },
  "series.defaults": { en: "Hair color\nHairstyle\nMain clothing\nFace appearance", ja: "髪色\n髪型\n主な衣服\n顔の見た目" },
  "series.disclosure": { en: "The reference and each candidate are sent as a pair to this connection. Generation prompts and metadata are not sent. Closing stops further comparisons and keeps completed results.", ja: "この接続先へ、基準画像と比較する画像を二枚一組で順に送ります。生成時のプロンプトや保存情報は送りません。閉じると次の比較へ進まず、確認済みの結果は残ります。" },
  "series.run": { en: "Compare selected images", ja: "選択した画像を比較" },
  "series.progress": { en: "Comparing… {done}/{total}", ja: "比較中… {done}/{total}" },
  "series.failed": { en: "Comparison stopped. Completed results were kept. Check the images and connection before starting a new comparison.", ja: "比較を続けられませんでした。確認済みの結果は残っています。画像と接続先を確認してから、新しい比較を開始してください。" },
  "series.selectResult": { en: "Select a saved comparison", ja: "保存した比較を選択" },
  "series.savedGroup": { en: "Saved image group", ja: "保存した画像群の結果" },
  "series.images": { en: " images", ja: "枚" },
  "series.pending": { en: "Not checked", ja: "未確認" },
  "series.running": { en: "No completed result yet", ja: "確認結果はまだありません" },
  "series.failedStatus": { en: "Could not check", ja: "確認できませんでした" },
  "series.empty": { en: "Start a comparison or select a saved result. Opening this screen does not resume unfinished checks.", ja: "比較を開始するか、保存した結果を選んでください。この画面を開くだけでは、途中の確認を再開しません。" },
  "conditions.title": { en: "Image condition check", ja: "画像の条件チェック" },
  "conditions.help": { en: "Check visible details against your conditions. Hidden or ambiguous details remain unknown. This is separate from anatomy checking and does not change or delete the image.", ja: "指定した条件に合うか、画像を見て確認します。見えない部分や曖昧な部分は「不明」です。人体の崩れ判定とは別で、画像の変更・削除はしません。" },
  "conditions.selectedImage": { en: "Image to check", ja: "確認する画像" },
  "conditions.criteria": { en: "Conditions — one per line", ja: "確認する条件（一行に一つ）" },
  "conditions.placeholder": { en: "Exactly one person\nWhite blouse\nReading a book\nBoth feet visible", ja: "人物は一人\n白いブラウスを着ている\n本を読んでいる\n両足の先まで見える" },
  "conditions.limit": { en: "Up to 16 conditions, 500 characters each. Describe what you want to see, including unwanted objects that should be absent.", ja: "16項目まで、各500文字以内です。人数・髪服・背景・行動のほか、見切れや不要物の有無も指定できます。" },
  "conditions.provider": { en: "Vision model connection", ja: "画像を確認する接続先" },
  "conditions.disclosure": { en: "The selected image and these conditions will be sent to this connection. Generation prompts and image metadata are not sent.", ja: "選んだ接続先へ画像と条件を送ります。生成時のプロンプトや画像内の保存情報は送りません。" },
  "conditions.noProvider": { en: "Add a vision-capable model in Settings → AI assistance first.", ja: "先に設定のAI補助で、画像に対応したモデルを接続してください。" },
