  "conditions.running": { en: "Checking…", ja: "確認中…" },
  "conditions.loading": { en: "Loading saved checks…", ja: "保存した結果を読み込み中…" },
  "conditions.stopClose": { en: "Cancel and close", ja: "中止して閉じる" },
