  "conditions.restore": { en: "Use the original AI answer", ja: "AIの元の回答を使う" },
  "conditions.reason": { en: "Reason for correction", ja: "訂正の理由" },
  "conditions.saveCorrection": { en: "Save correction", ja: "訂正を保存" },
  "conditions.stale": { en: "The image has changed or is unavailable. This saved check describes the earlier image. Select an available image and run a new check.", ja: "画像が差し替わったか、見つかりません。この結果は以前の画像のものです。画像を選び直して再確認してください。" },
  "conditions.failed": { en: "The image could not be checked. Check the connection and vision-model support, then try again. No judgment was saved.", ja: "画像を確認できませんでした。接続先とモデルの画像対応を確認して、再試行してください。判定は保存していません。" },
  "conditions.loadFailed": { en: "Saved checks could not be loaded. Close this window and open it again.", ja: "確認結果を読み込めませんでした。いったん閉じて、もう一度開いてください。" },
  "conditions.correctionFailed": { en: "The correction could not be saved. The image or saved check may have changed. Close and reopen this window before trying again.", ja: "訂正を保存できませんでした。画像や確認結果が更新された可能性があります。いったん閉じて、最新の結果を開き直してください。" },
  "conditions.filter": { en: "Filter saved condition checks", ja: "保存した条件判定で絞る" },
