  "promptChoices.empty": { en: "(empty text)", ja: "（空の文章）" },
  "promptChoices.nested": { en: "Pinning a nested choice also pins its parent choices. Clearing a parent also clears its dependent pins.", ja: "入れ子の候補を固定すると、その候補を含む親の選択も固定します。親の固定を解除すると、その子の固定も解除します。" },
  "promptChoices.changedDuringPreview": { en: "The input changed during expansion. Preview it again.", ja: "展開中に入力が変わりました。もう一度プレビューしてください。" },
  "promptChoices.stalePreview": { en: "The prompt or styles changed. Preview the new input. Clear any existing pins first.", ja: "プロンプトかスタイルが変わりました。固定中の候補があれば解除して、もう一度プレビューしてください。" },
  "promptChoices.promptChanged": { en: "The prompt or applied styles changed since these choices were pinned. Clear the pins in the expansion preview, then select them again.", ja: "固定した後にプロンプトか適用スタイルが変わりました。展開プレビューで固定を解除し、選び直してください。" },
  "promptChoices.optionsChanged": { en: "A pinned choice is no longer available or its candidates changed. Clear the pins in the expansion preview, then select them again.", ja: "固定した候補が見つからないか、候補の内容が変わっています。展開プレビューで固定を解除し、選び直してください。" },
  "promptChoices.expansionLimit": { en: "The prompt contains too many nested choices. Reduce the nesting or number of choices and try again.", ja: "候補の展開数が多すぎます。入れ子や候補の数を減らして再試行してください。" },
  "imageCheck.title": { en: "Generated image check", ja: "生成画像のチェック" },
  "generation.error.imageCheckRuntimeUnsupported": { en: "Image checking is unavailable for the selected generation engine. Select the ComfyUI engine, or turn off image checking and retry.", ja: "選択中の生成エンジンでは画像をチェックできません。ComfyUIを選ぶか、画像のチェックをOFFにして再試行してください。" },
  "generation.error.imageCheckSettingsInvalid": { en: "The image-check settings could not be read. Open Check settings, select the AI connection again, and save.", ja: "画像チェックの設定を読み込めませんでした。「チェック設定」でAI接続先を選び直し、保存してください。" },
  "imageCheck.checking": { en: "Checking the image before enhancement…", ja: "補正・拡大の前に画像を確認しています…" },
  "imageCheck.toggle": { en: "Check images", ja: "画像をチェック" },
  "imageCheck.settings": { en: "Check settings", ja: "チェック設定" },
  "imageCheck.description": { en: "Check visible anatomical defects before enhancement. This does not check whether an image matches your prompt.", ja: "手足や身体の崩れを、拡大・補正の前に確認します。プロンプトどおりに描かれたかを調べる機能とは別です。" },
  "imageCheck.defaultEnabled": { en: "Enable checking by default", ja: "生成画像のチェックを初期状態でONにする" },
  "imageCheck.provider": { en: "Image-capable AI connection", ja: "画像を判定するAI接続先" },
  "imageCheck.method": { en: "Check with", ja: "判定方法" },
  "imageCheck.methodLLM": { en: "Image-capable LLM", ja: "画像対応LLM" },
  "imageCheck.codexHelp": { en: "Use an installed, signed-in Codex CLI. Each check sends one image to Codex and consumes your Codex usage allowance. It does not use the API connection above. No commands or file edits are permitted.", ja: "インストール・ログイン済みのCodex CLIを使います。判定ごとに画像を一枚送信し、Codexの利用枠を消費します。上のAPI接続設定は使いません。コマンド実行やファイル編集は許可しません。" },
  "imageCheck.codexChecking": { en: "Looking for Codex…", ja: "Codexを確認しています…" },
  "imageCheck.codexAvailable": { en: "Codex found. Sign in with the CLI before checking images.", ja: "Codexが見つかりました。画像をチェックする前にCLIでログインしてください。" },
  "imageCheck.codexSetupRequired": { en: "A supported Codex CLI was not found. Install or update the CLI, then check again.", ja: "対応するCodex CLIが見つかりません。CLIをインストールまたは更新し、再確認してください。" },
