  "common.error.external": { en: "External tool operation failed. Check the tool connection in Settings and try again.", ja: "外部ツールの処理に失敗しました。Settingsで接続を確認してから再試行してください。" },
  "common.error.externalSettingsSave": { en: "Could not save external tool settings. Check the selected path and try again.", ja: "外部ツール設定を保存できませんでした。選択したパスを確認してから再試行してください。" },
  "common.error.pathSelection": { en: "The selected file or folder is unavailable. Choose it again and retry.", ja: "選択したファイルまたはフォルダを利用できません。もう一度選択して再試行してください。" },
  "common.error.eagleSettingsInvalid": { en: "Enter an Eagle URL such as http://localhost:41595 without credentials or an API path.", ja: "Eagle URLを http://localhost:41595 の形式で、認証情報やAPIパスを含めず入力してください。" },
  "common.error.topazProcess": { en: "Topaz processing failed. Check the Topaz path, source image, and selected settings, then try again.", ja: "Topaz処理に失敗しました。Topazのパス、元画像、選択中の設定を確認してから再試行してください。" },
  "common.error.eagleImport": { en: "Could not send the image to Eagle. Check Eagle connection and the selected image, then try again.", ja: "画像をEagleへ送れませんでした。Eagleの接続と選択中の画像を確認してから再試行してください。" },
  "common.error.eagleFolders": { en: "Could not load Eagle folders. Check the Eagle connection, then refresh the folder list.", ja: "Eagleのフォルダを読み込めませんでした。Eagleの接続を確認して、フォルダ一覧を更新してください。" },
  "common.error.outputImageNotFound": { en: "Could not find that output image. Refresh the Library or choose another image.", ja: "その出力画像が見つかりません。画像管理を更新するか別の画像を選んでください。" },
