  "common.error.managedDownloadDestination": { en: "Choose an Asteria-managed download destination and try again.", ja: "Asteriaが管理するダウンロード先を選んでから再試行してください。" },
  "common.error.outputImageUnreadable": { en: "Could not read that output image. Check the file and try again.", ja: "その出力画像を読み込めませんでした。ファイルを確認してから再試行してください。" },
  "common.error.outputImageNotRegistered": { en: "Choose an image from Asteria history or refresh the Library and try again.", ja: "Asteriaの履歴にある画像を選ぶか、画像管理を更新してから再試行してください。" },
  "common.error.historyDelete": { en: "Could not delete the history item. Refresh the Library and check the output files.", ja: "履歴項目を削除できませんでした。画像管理を更新し、出力ファイルを確認してください。" },
  "common.error.orphanCleanupGenerationActive": { en: "Generation is still finalizing files. Wait for it to finish, then retry cleanup.", ja: "生成ファイルの確定処理中です。完了を待ってからクリーンアップを再実行してください。" },
  "common.error.assetImageUnsupported": { en: "Choose a PNG, JPEG, or WebP image and try again.", ja: "PNG、JPEG、またはWebP画像を選んでから再試行してください。" },
