  "common.error.sourceImageChanged": { en: "The source image changed after it was loaded. Refresh the view or choose the image again.", ja: "読み込み後に入力画像が変更されました。画面を更新するか、画像を選び直してください。" },
  "common.error.imageCrop": { en: "Could not crop the source image. Check the image and selected area, then try again.", ja: "入力画像を切り抜けませんでした。画像と選択範囲を確認してから再試行してください。" },
  "common.error.modelStorageSave": { en: "Could not save model storage settings. Check the model root path and try again.", ja: "モデル保存設定を保存できませんでした。モデルルートのパスを確認してから再試行してください。" },
  "common.error.modelSelectionSave": { en: "Could not save model selections. Refresh model assets or choose the models again.", ja: "モデル選択を保存できませんでした。モデルアセットを更新するか、モデルを選び直してください。" },
  "common.error.modelSelectionStale": { en: "The model profile changed before saving. Refresh model assets and choose the models again.", ja: "保存前にモデルプロファイルが変更されました。モデルアセットを更新して、モデルを選び直してください。" },
