  "lora.error.prepareCopyMachineComparison": { en: "Could not prepare the copy-machine LoRA comparison. Review the comparison settings and try again.", ja: "コピー機LoRAの比較を準備できませんでした。比較設定を確認してから再試行してください。" },
  "lora.error.runCopyMachineComparison": { en: "Could not run the copy-machine LoRA comparison. Review the comparison settings and try again.", ja: "コピー機LoRAの比較を実行できませんでした。比較設定を確認してから再試行してください。" },
