  "lora.error.createDataset": { en: "Could not create the LoRA training dataset. Check the dataset name and preset, then try again.", ja: "LoRA学習データセットを作成できませんでした。データセット名とプリセットを確認してから再試行してください。" },
  "lora.error.addDatasetImage": { en: "Could not add the image to the LoRA training dataset. Check the image path and try again.", ja: "LoRA学習データセットへ画像を追加できませんでした。画像パスを確認してから再試行してください。" },
  "lora.error.importDatasetFolder": { en: "Could not import the LoRA dataset folder. Check the folder and supported images, then try again.", ja: "LoRAデータセットフォルダを取り込めませんでした。フォルダと対応画像を確認してから再試行してください。" },
  "lora.error.importCaptionSources": { en: "Could not import LoRA caption sources. Check the source folder and try again.", ja: "LoRAキャプション証跡を取り込めませんでした。取り込み元フォルダを確認してから再試行してください。" },
  "lora.error.refreshCaptionSources": { en: "Could not refresh LoRA caption sources. Check the source settings and try again.", ja: "LoRAキャプション証跡を更新できませんでした。証跡設定を確認してから再試行してください。" },
  "lora.error.exportAnimaTaggerSidecars": { en: "Could not export anima-tagger RON sidecars. Check the sidecar settings and try again.", ja: "anima-taggerのRONサイドカーを書き出せませんでした。サイドカー設定を確認してから再試行してください。" },
  "lora.error.saveCaptionExportSettings": { en: "Could not save LoRA caption export settings. Review the export options and try again.", ja: "LoRAキャプション書き出し設定を保存できませんでした。書き出し設定を確認してから再試行してください。" },
  "lora.error.saveCharacterCaptionPolicy": { en: "Could not save the character caption policy. Review the trigger token and identity tags, then try again.", ja: "キャラクターキャプション規約を保存できませんでした。トリガートークンと固定特徴タグを確認してから再試行してください。" },
  "lora.error.saveCaption": { en: "Could not save the LoRA training caption. Review the caption and try again.", ja: "LoRA学習キャプションを保存できませんでした。キャプションを確認してから再試行してください。" },
  "lora.error.saveCaptionSource": { en: "Could not save the LoRA caption source. Review the source fields and try again.", ja: "LoRAキャプション証跡を保存できませんでした。証跡の入力内容を確認してから再試行してください。" },
