  "common.error.runtimeStart": { en: "Could not start generation setup. Check the runtime setup in Settings and try again.", ja: "生成環境を起動できませんでした。Settingsの実行環境設定を確認してから再試行してください。" },
  "common.error.runtimeCoreInstall": { en: "Could not install generation setup. Check the setup path and try again.", ja: "生成環境をインストールできませんでした。セットアップ先を確認してから再試行してください。" },
  "common.error.runtimeCoreRepair": { en: "Could not repair generation setup. Check the setup path and try again.", ja: "生成環境を修復できませんでした。セットアップ先を確認してから再試行してください。" },
