  "common.error.settingsSave": { en: "Could not save Settings. Review the entered paths and values, then try again.", ja: "設定を保存できませんでした。入力したパスや値を確認してから再試行してください。" },
  "common.error.promptAssist": { en: "Prompt assist failed. Review the provider settings and try again.", ja: "プロンプト支援に失敗しました。プロバイダー設定を確認してから再試行してください。" },
  "common.error.wildcards": { en: "Could not load wildcards. Refresh the prompt tools and try again.", ja: "Wildcardsを読み込めませんでした。プロンプトツールを更新してから再試行してください。" },
  "common.error.notFound": { en: "The selected item could not be found. Refresh the view and try again.", ja: "選択した項目が見つかりません。画面を更新してから再試行してください。" },
  "extensions.error.assetUnavailable": { en: "The extension interface could not be loaded. Restart Asteria, then reinstall or disable the extension if it still fails.", ja: "拡張機能の画面を読み込めませんでした。Asteriaを再起動し、解決しない場合は拡張機能を再インストールするか無効にしてください。" },
  "extensions.error.actionPending": { en: "Another change to this extension is waiting for a restart. Restart Asteria before trying again.", ja: "この拡張機能には再起動待ちの変更があります。Asteriaを再起動してから再試行してください。" },
  "extensions.error.catalogInvalid": { en: "The extension catalog could not be read. Refresh it later or install from a trusted URL or folder.", ja: "拡張機能カタログを読み込めませんでした。時間をおいて更新するか、信頼できるURLまたはフォルダーから導入してください。" },
  "extensions.error.catalogIncompatible": { en: "This extension is not available for this version of Asteria. Choose a compatible extension or use a compatible version of Asteria.", ja: "この拡張機能は現在のAsteriaでは利用できません。対応する拡張機能またはAsteriaのバージョンを選択してください。" },
  "extensions.error.catalogPartial": { en: "Some catalog entries were skipped because they were invalid. Review the remaining entries or refresh the catalog.", ja: "無効な項目があったため、カタログの一部を除外しました。表示中の項目を確認するか、カタログを更新してください。" },
  "extensions.error.catalogUnavailable": { en: "The extension catalog is unavailable. Check your connection and refresh it, or use the last cached catalog.", ja: "拡張機能カタログに接続できません。接続を確認して更新するか、保存済みのカタログを使用してください。" },
  "extensions.error.confirmationRequired": { en: "Confirm this extension change and try again.", ja: "この拡張機能への変更を確認してから再試行してください。" },
  "extensions.error.conflict": { en: "This extension or version is already installed, or another change is in progress. Review Installed extensions and try again.", ja: "この拡張機能または同じバージョンはすでに導入されているか、別の変更を処理中です。導入済み一覧を確認してから再試行してください。" },
  "extensions.error.inactive": { en: "This extension is not active. Enable or reinstall it, then restart Asteria.", ja: "この拡張機能は有効ではありません。有効化または再インストールしてからAsteriaを再起動してください。" },
  "extensions.error.installFailed": { en: "Asteria could not install the extension. Check the source and connection, then try again.", ja: "拡張機能を導入できませんでした。導入元と接続を確認してから再試行してください。" },
  "extensions.error.installMissing": { en: "The extension files are missing. Reinstall the extension before enabling it.", ja: "拡張機能のファイルが見つかりません。有効にする前に拡張機能を再インストールしてください。" },
  "extensions.error.integrityMismatch": { en: "The extension package did not match its expected size, version, or checksum. Refresh the source and download it again.", ja: "拡張機能パッケージのサイズ、バージョン、またはチェックサムが一致しません。導入元を更新して再度ダウンロードしてください。" },
  "extensions.error.loadFailed": { en: "The extension could not start. Restart Asteria in Safe Mode, then disable or reinstall the extension.", ja: "拡張機能を起動できませんでした。ランチャーのSafe ModeでAsteriaを再起動し、拡張機能を無効化または再インストールしてください。" },
  "extensions.error.notFound": { en: "The extension could not be found. Refresh Extensions and try again.", ja: "拡張機能が見つかりません。Extensionsを更新してから再試行してください。" },
  "extensions.error.packageInvalid": { en: "This package is not compatible with Asteria or is missing required extension files. Choose another version or contact its author.", ja: "このパッケージはAsteriaと互換性がないか、必要な拡張機能ファイルが不足しています。別のバージョンを選ぶか、作者へ確認してください。" },
  "extensions.error.requestInvalid": { en: "Asteria could not use those extension details. Review your selections and try again.", ja: "指定された拡張機能の内容を使用できませんでした。選択内容を確認してから再試行してください。" },
  "extensions.error.sourceInvalid": { en: "The extension source is not valid. Choose a GitHub or HTTPS ZIP, a local ZIP, or an extension folder and try again.", ja: "拡張機能の導入元が正しくありません。GitHubまたはHTTPSのZIP、ローカルZIP、拡張機能フォルダーのいずれかを選んで再試行してください。" },
  "extensions.error.sourceMismatch": { en: "The downloaded extension does not match the catalog entry. Refresh the catalog and try again.", ja: "ダウンロードした拡張機能がカタログの内容と一致しません。カタログを更新してから再試行してください。" },
  "extensions.error.stateInvalid": { en: "The saved extension state could not be read. Restart Asteria in Safe Mode, then reinstall or disable the extension.", ja: "保存された拡張機能の状態を読み込めませんでした。ランチャーのSafe ModeでAsteriaを再起動し、拡張機能を再インストールするか無効にしてください。" },
  "extensions.error.unsupported": { en: "This extension does not support that change. Review its installed version and available actions.", ja: "この拡張機能ではその変更を使用できません。導入済みバージョンと利用可能な操作を確認してください。" },
