  "settings.discord.publishHelp": { en: "Use “Publish to Discord” in Generate. Editing Generate later does not change the bot settings until you publish again.", ja: "Generate画面の「Discordへ公開」で設定します。その後Generate画面を編集しても、もう一度公開するまではBotの設定は変わりません。" },
  "settings.discord.policyTitle": { en: "Who can use the bot", ja: "Botを使える場所とユーザー" },
  "settings.discord.allowlistHelp": { en: "A request is accepted only when both its server/channel and its user/role are allowed. For personal use, enter your server ID and your user ID.", ja: "「使えるサーバーまたはチャンネル」と「使えるユーザーまたはロール」の両方に当てはまる人だけが画像生成できます。個人利用なら、自分のサーバーIDとユーザーIDを1件ずつ入力すれば十分です。" },
  "settings.discord.idCopyHelp": { en: "To copy IDs: Discord User Settings → Advanced → enable Developer Mode. Then right-click a server, channel, user, or role and choose Copy ID.", ja: "IDをコピーする準備：Discordの「ユーザー設定」→「詳細設定」→「開発者モード」をオンにします。その後、サーバー・チャンネル・ユーザー・ロールを右クリックして「IDをコピー」を選びます。" },
  "settings.discord.registrationGuild": { en: "Server for bot commands", ja: "Botコマンドを登録するサーバーID" },
  "settings.discord.registrationServerHelp": { en: "Right-click the server icon and choose Copy Server ID. Commands appear in this server first.", ja: "Discord左側のサーバーアイコンを右クリックし、「サーバーIDをコピー」を選びます。このサーバーにBotのコマンドが登録されます。" },
  "settings.discord.fallbackChannel": { en: "Channel for fallback messages", ja: "予備の送信先チャンネルID" },
  "settings.discord.fallbackChannelHelp": { en: "Right-click the channel and choose Copy Channel ID. Leave blank when you do not need fallback delivery.", ja: "対象チャンネルを右クリックし、「チャンネルIDをコピー」を選びます。予備の送信先が不要なら空欄で構いません。" },
  "settings.discord.guildAllowlist": { en: "Allowed server IDs", ja: "使えるサーバーID" },
  "settings.discord.serverAllowlistHelp": { en: "One ID per line. Right-click each server icon and choose Copy Server ID.", ja: "1行に1件入力します。Discord左側のサーバーアイコンを右クリックし、「サーバーIDをコピー」を選びます。" },
  "settings.discord.channelAllowlist": { en: "Allowed channel IDs", ja: "使えるチャンネルID" },
  "settings.discord.channelAllowlistHelp": { en: "Optional. Add these when the bot should work only in specific channels.", ja: "特定のチャンネルだけで使わせたい場合に入力します。サーバー全体で使うなら空欄でも構いません。" },
  "settings.discord.userAllowlist": { en: "Allowed user IDs", ja: "使えるユーザーID" },
